<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>平台接收关系</h2><p>独立管理平台接收方、核验事实及本地启停；不执行资金。</p></div><Button type="primary" :disabled="blocked" @click="create">新增关系</Button></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div class="ui-search"><label>收付通配置<BusinessSelect v-model="configId" type="channel-configs"/></label><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><Table class="s1-list-table" v-compact-table :columns="columns" :data="records" :loading="loading" no-data-text="暂无平台接收关系"><template slot="name" slot-scope="{row}"><button class="ui-link ui-primary-name" @click="detail(row.id)">{{row.displayName}}</button><span class="ui-meta">{{row.id}}</span></template><template slot="config" slot-scope="{row}">{{names[row.configId]||'配置名称不可读'}}<span class="ui-meta">{{status(row.mode)}}</span></template><template slot="state" slot-scope="{row}"><StatusTag :value="row.state"/><span>{{row.enabled?'本地启用':'本地停用'}}</span></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">详情与核验</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="changePage"/><Modal v-model="show" title="新建平台接收关系" width="820" :mask-closable="false" footer-hide><div class="s1-ui"><Alert show-icon>配置决定环境和模式。保存后仍未核验、停用；不会自动替代现有关系。</Alert><Form :model="form" :label-width="150"><FormItem label="收付通配置" required><BusinessSelect v-model="form.configId" type="channel-configs" :disabled="blocked" @selected="config=$event;dirty=true"/></FormItem><FormItem label="平台主体名称" required><Input v-model="form.displayName" maxlength="120" :disabled="blocked" @on-change="dirty=true"/></FormItem><FormItem v-if="config&&config.mode==='MOCK'" label="模拟接收方账号" required><Input v-model="form.mockAccount" maxlength="64" placeholder="MOCK_ 开头，仅合成测试数据" :disabled="blocked" @on-change="dirty=true"/></FormItem><FormItem v-else-if="config&&config.mode==='REAL'" label="真实账号受控引用" required><Input v-model="form.accountReference" maxlength="64" placeholder="只填部署凭据引用，不粘贴秘密" :disabled="blocked" @on-change="dirty=true"/></FormItem><FormItem label="原因" required><Input v-model="form.reason" type="textarea" maxlength="500" :disabled="blocked" @on-change="dirty=true"/></FormItem></Form><p v-if="error" class="ui-error">{{error}}</p><footer class="ui-form-footer"><Button @click="cancel">取消</Button><Button type="primary" :loading="busy" :disabled="blocked" @click="save">保存未核验关系</Button></footer></div></Modal></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';import BusinessSelect from './components/BusinessSelect';import {stage1Confirm} from '../confirm';export default {mixins:[page],components:{PageStatus,StatusTag,BusinessSelect},data:()=>({configId:'',names:{},show:false,config:null,form:{},columns:[{title:'平台主体',slot:'name',minWidth:230},{title:'配置／模式',slot:'config',minWidth:220},{title:'核验／启停',slot:'state',minWidth:180},{title:'操作',slot:'operations',width:145}]}),mounted(){this.initializeList(['configId']);this.reload();},methods:{async reload(){const value=await this.load('/receivers',{configId:this.configId||undefined});if(!value)return;const ids=[...new Set(this.records.map(r=>r.configId))],names={};if(ids.length)try{const v=await this.ui('/lookups/channel-configs',{selected:ids.join(','),pageSize:100});v.records.forEach(r=>{names[r.id]=r.name;});}catch(_){}if(value.records===this.records)this.names=names;},search(){this.page=1;this.remember(['configId']);this.reload();},reset(){this.configId='';this.search();},changePage(v){this.page=v;this.remember(['configId']);this.reload();},create(){this.form={configId:this.configId,displayName:'',mockAccount:'',accountReference:'',reason:''};this.config=null;this.show=true;},async save(){if(!this.form.configId||!this.form.displayName||!this.form.reason){this.error='请选择配置并填写主体名称、原因。';return;}const body={configId:this.form.configId,displayName:this.form.displayName,reason:this.form.reason};if(this.config&&this.config.mode==='MOCK')body.mockAccount=this.form.mockAccount;else if(this.config&&this.config.mode==='REAL')body.accountReference=this.form.accountReference;else {this.error='请等待配置模式读取完成。';return;}try{const result=await this.run('/receivers',body);if(result){this.show=false;this.dirty=false;this.detail(result.id);}}catch(_){}},cancel(){const close=()=>{this.show=false;this.dirty=false;};if(this.dirty)stage1Confirm({title:'放弃未保存关系？',content:'关闭不会创建或替换接收关系。',onOk:close});else close();}}};</script>
